export type StudyCondition = 'findings_only' | 'findings_plus_explanation';

export const STUDY_CONDITIONS: readonly StudyCondition[] = ['findings_only', 'findings_plus_explanation'];

export interface StudyItem {
  story_id: string;
  condition: StudyCondition;
}

/** Participant code -> ordered list of items. Order is defined by the config, never generated by the UI. */
export interface StudyConfig {
  description?: string;
  participants: Record<string, StudyItem[]>;
}

export interface StudyRecord {
  participant_code: string;
  story_id: string;
  condition: StudyCondition;
  /** 1-based position in the participant's sequence. */
  order: number;
  fixed_text: string;
  time_ms: number;
  clarity: number;
  usefulness: number;
  trust: number;
}

export const STUDY_CSV_COLUMNS: readonly (keyof StudyRecord)[] = [
  'participant_code',
  'story_id',
  'condition',
  'order',
  'fixed_text',
  'time_ms',
  'clarity',
  'usefulness',
  'trust',
];
